            chmax(dp[i+2][3],dp[i][2]+win(1,i,1,i+1,1,i+2));
        }
        // 3 ->
        if (i + 3 <= n){
            chmax(dp[i+1][2],dp[i][3]+win(0,i,0,i+1,0,i+2));
        }
        if (i + 2 <= n){
            chmax(dp[i+2][0],dp[i][3]+win(0,i,0,i+1,1,i+1));
        }
        // 4 ->
        if (i + 3 <= n){
            chmax(dp[i+2][1],dp[i][4]+win(0,i,0,i+1,0,i+2));
        }
    }
