int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while(t--){
        int n, s1, s2;
        cin >> n >> s1 >> s2;

        // Build the first graph.
        int m1;
        cin >> m1;
        vector<vector<int>> graph1(n+1);
        // Using an unordered_set for quick lookup.
        vector<unordered_set<int>> adj1(n+1);
        for (int i = 0; i < m1; i++){
            int u, v;
            cin >> u >> v;
            graph1[u].push_back(v);
            graph1[v].push_back(u);
            adj1[u].insert(v);
            adj1[v].insert(u);
        }

        // Build the second graph.
        int m2;
        cin >> m2;
        vector<vector<int>> graph2(n+1);
        vector<unordered_set<int>> adj2(n+1);
        for (int i = 0; i < m2; i++){
            int u, v;
            cin >> u >> v;
            graph2[u].push_back(v);
            graph2[v].push_back(u);
            adj2[u].insert(v);
            adj2[v].insert(u);
        }

        // Mark safe vertices:
        // A vertex v is safe if there exists some neighbor u (in graph1)
        // that is also a neighbor of v in graph2.
        vector<bool> safe(n+1, false);
        for (int v = 1; v <= n; v++){
            for (int u : graph1[v]){
                if (adj2[v].find(u) != adj2[v].end()){
                    safe[v] = true;
                    break;
                }
            }
        }

        // Special case: if tokens start on the same safe vertex, answer is 0.
        if (s1 == s2 && safe[s1]){
            cout << 0 << "\n";
            continue;
        }

        // We'll perform Dijkstra’s algorithm in the state space.
        // Each state is (v1, v2) with cost d.
        const int INF = 1000000000;
        vector<vector<int>> dist(n+1, vector<int>(n+1, INF));
        dist[s1][s2] = 0;

        // Priority queue holds (cost, v1, v2) with smallest cost at the top.
        typedef tuple<int, int, int> state;
        priority_queue< state, vector<state>, greater<state> > pq;
        pq.push({0, s1, s2});

        int ans = INF;
        while (!pq.empty()){
            auto [d, v1, v2] = pq.top();
            pq.pop();
            if (d != dist[v1][v2])
                continue;
            // If both tokens are at the same vertex and that vertex is safe,
            // then an infinite zero–cost continuation is possible.
            if (v1 == v2 && safe[v1]){
                ans = d;
                break;
            }
            // Explore all possible transitions.
            for (int nxt1 : graph1[v1]){
                for (int nxt2 : graph2[v2]){
                    int nd = d + abs(nxt1 - nxt2);
                    if (nd < dist[nxt1][nxt2]){
                        dist[nxt1][nxt2] = nd;
                        pq.push({nd, nxt1, nxt2});
                    }
                }
            }
        }

        cout << (ans == INF ? -1 : ans) << "\n";
    }
    return 0;
}

