void solve() {
    LL(n, k);
    VEC(ll, A, n);
    VEC(ll, B, n);
    ll ans   = 0;
    ll ma0   = -1;
    int idx0 = -1;
    ll ma1   = -1;
    int idx1 = -1;
    fori(i, n) {
        if (B[i] == 0) {
            if (chmax(ma0, A[i])) idx0 = i;
        } else {
            if (chmax(ma1, A[i])) idx1 = i;
        }
    }
    if (idx1 != -1) {
        ll tmp = ma1 + k;
        vec(ll, C, 0);
        fori(i, n) {
            if (i != idx1) {
                C.push_back(A[i]);
            }
        }
        sort(all(C));
        tmp += C[(len(C) - 1) / 2];
        chmax(ans, tmp);
    }
    if (idx0 != -1) {
        ll l = 0;
        ll r = 1LL << 40;
        while (r - l > 1) {
            ll mid = (l + r) / 2;
            vec(ll, C, 0);
            fori(i, n) {
                if (i == idx0) continue;
                if (A[i] >= mid) {
                    C.push_back(0);
                } else if (B[i] == 1) {
                    C.push_back(mid - A[i]);
                }
            }
            if (len(C) < (n + 1) / 2) {
                r = mid;
                continue;
            }
            ll tot = 0;
            sort(all(C));
            fori(i, (n + 1) / 2) {
                tot += C[i];
            }
            if (tot <= k) {
                l = mid;
            } else {
                r = mid;
            }
        }
        chmax(ans, l + ma0);
    }
    print(ans);
}

