struct Edge {
	int u, v;

	static Edge from(vector<int> a) {
		const int n = a.size();
		vector<char> b(n + 1);
		for (int x : a) {
			if (x <= n) {
				b[x] = 1;
			}
		}
		int i = 0;
		while (b[i]) {
			++i;
		}
		int j = i + 1;
		while (j <= n && b[j]) {
			++j;
		}
		return {i, j};
	}
};

void remax(int& x, int y) {
	x = (x > y) ? x : y;
}

void solve() {
	int n = nxt(), m = nxt();
	vector<Edge> edges(n);
	for (int i = 0; i < n; ++i) {
		vector<int> a(nxt());
		generate(all(a), nxt);
		edges[i] = Edge::from(a);
	}
	sort(all(edges), [&](const Edge& a, const Edge& b) {
		return a.u < b.u;
	});
	reverse(all(edges));

	map<int, int> if_start_from;
	auto get = [&](int i) -> int& {
		if (auto it = if_start_from.find(i); it != if_start_from.end()) {
			return it->second;
		} else {
			return if_start_from[i] = i;
		}
	};

	for (const auto& [u, v] : edges) {
		remax(get(u), get(v));
	}
	int total_mx = 0;
	map<int, int> by_u;
	for (auto [u, v] : edges) {
		by_u[u] += 1;
		remax(total_mx, u);
	}
	for (auto [k, v] : by_u) {
		if (v > 1) {
			remax(total_mx, get(k));
		}
	}

	long long ans = 1ll * m * (m + 1) / 2;
	{
		int tmp = min(m, total_mx);
		ans -= 1ll * tmp * (tmp + 1) / 2;
		ans += 1ll * (tmp + 1) * total_mx;
	}
	for (auto [k, v] : if_start_from) {
		if (k <= m && v > total_mx) {
			ans -= max(total_mx, k);
			ans += v;
		}
	}
	cout << ans << "\n";
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(nullptr);

	int t = nxt();
	while (t--) {
		solve();
	}

	return 0;
}

