int ksm(int n,int m){
    int ans=1;
    while(m){
        if(m&1)ans=ans*n%M;
        n=n*n%M;m/=2;
    }return ans;
}
void init(int n){
    for(int i=0;i<n;i++){
        d[i]=d[i/2]/2;
        if(i&1)d[i]+=n/2;
    }
}
void NTT(int n,int *f,int opt){
    for(int i=0;i<n;i++)if(d[i]>i)swap(f[i],f[d[i]]);
    for(int d=2;d<=n;d*=2){
        int w=ksm(g,(M-1)/d);
        if(!opt)w=ksm(w,M-2);
        for(int i=0;i<n;i+=d){
            int pw=1;
            for(int j=i;j<i+d/2;j++){
                int x=f[j],y=f[j+d/2];
                f[j]=(x+pw*y)%M;f[j+d/2]=(x-pw*y%M+M)%M;
                pw=pw*w%M;
            }
        }
    }
    if(!opt){
        int inv=ksm(n,M-2);
        for(int i=0;i<n;i++)f[i]=f[i]*inv%M;
    }
}
int Co(int n,int m){
	return fc[n]*fv[m]%M*fv[n-m]%M;
