    cin.tie(nullptr);

    cin >> t;
    while (t--)
    {
        cin >> n >> q;
        for (int i = 1; i <= n; i++)
            cin >> a[i], sum[i] = sum[i - 1] + a[i];
        build(1, 1, n);
        vector<int> ans(n + 2);
        for (int i = 1; i <= n; i++)
        {
            int l = i, r = i;
            i64 cur = a[i];
            while (l > 1 && cur < 1e9)
            {
                bool done = false;
                if (l > 1)
                {
                    int pos = find1(1, 1, n, 1, l - 1, cur);
                    if (pos + 1 < l)
                    {
                        done = true;
                        cur += sum[l - 1] - sum[pos];
                        l = pos + 1;
                    }
                }
                if (r < n && !done)
                {
                    int pos = find2(1, 1, n, r + 1, n, cur);
                    if (r + 1 < pos)
                    {
                        int ll = r + 1, rr = pos - 1, mid = ll;
                        while (ll < rr)
                        {
                            mid = ll + rr >> 1;
                            if (sum[mid] - sum[r] + cur >= a[l - 1])
                                rr = mid;
                            else
                                ll = mid + 1;
                        }
                        done = true;
                        cur += sum[mid] - sum[r];
                        r = mid;
                    }
                }
                if (!done)
                    break;
            }
            if (cur < 1e9 && l > 1)
                continue;
            ans[r]++;
            cur += sum[l - 1], l = 1;
            if (r < n && cur < 1e9)
            {
                while (r < n && cur < 1e9)
                {
                    bool done = false;
                    if (r < n)
                    {
                        int pos = find2(1, 1, n, r + 1, n, cur);
                        if (r + 1 < pos)
                        {
                            done = true;
                            cur += sum[pos - 1] - sum[r];
                            r = pos - 1;
                        }
                    }
                    if (!done)
                        break;
                }
                if (cur >= 1e9 || r == n)
                    ans[n + 1]--;
                else
                    ans[r + 1]--;
            }
        }
        for (int i = 1; i <= n; i++)
        {
            ans[i] += ans[i - 1];
            cout << ans[i] << " \n"[i == n];
        }
    }
}
