void solve(){
    int n, m;
    cin >> n >> m;
    vector<int> a(n * m);
    for (int i = 0; i < n * m; i++){
        cin >> a[i];
    }
    vector<int> b(n * m);
    for (int i = 0; i < n * m; i++){
        cin >> b[i];
    }    

    int good = 0;
    int u = 0;

    int ans = 0;

    for (int i = 0; i < n * m; i += m){
        vector<int> x;
        for (int j = u; j < u + m; j++){
            x.push_back(a[j]);
        }
        vector<int> y;
        for (int j = i; j < i + m; j++){
            y.push_back(b[j]);
        }
        int ind = 0;
        int ind2 = 0;

        int u2 = 0;
        while(1){
            if (ind <= good){
                ind2 = max(ind2, ind);
            }
            if (x[ind] != y[u2] && ind > good){
                break;
            }
            while(u2 < m && x[ind] != y[u2]){
                u2++;
            }
            if (u2 < m && x[ind] == y[u2]){
                ind++;
                u2++;
            }
            if (ind <= good){
                ind2 = max(ind2, ind);
            }
            if (u2 >= m){
                break;
            }
        }
        if (u2 == m){
            ind2 = max(ind, ind2);
        }
        ind = ind2;

        ind--;
        good += (m - (ind + 1));
        ans += (m - (ind + 1));
        u += (ind + 1);
    }

    cout << ans << '\n';
}

