struct Node {
	int a, p, s, e, ps, pe, es, ee;
	Node(){
		a = -(int)1e18;
		p = -(int)1e18;
		s = -(int)1e18;
		e = -(int)1e18;
		ps = -(int)1e18;
		pe = -(int)1e18;
		es = -(int)1e18;
		ee = -(int)1e18;
	}
	Node(int x, int y){
		a = x;
		p = x + y;
		s = x + y;
		e = x + y + y;
		ps = -(int)1e18;
		pe = -(int)1e18;
		es = -(int)1e18;
		ee = -(int)1e18;
	}
};

Node merge(Node a, Node b){
	if(a.a == -(int)1e18)return b;
	if(b.a == -(int)1e18)return a;
	Node c;
	//cerr << "merge\n";
	c.a = a.a + b.a;
	c.p = max(a.a + b.p, a.p);
	c.s = max(a.s + b.a, b.s);
	c.e = max({a.e, b.e, a.s + b.p});
	c.ps = max({a.ps + b.a, a.a + b.ps, a.p + b.s});
	c.pe = max({a.pe, a.ps + b.p, a.p + b.e, a.a + b.pe});
	c.es = max({b.es, a.s + b.ps, a.e + b.s, a.es + b.a});
	c.ee = max({a.ee, a.s + b.pe, a.e + b.e, a.es + b.p, b.ee});
	return c;
}

struct SegTree{
	int size;
	vector<Node>arr;
	void init(int n){
		size = 1;
		while(size<n)size*=2;
		arr.resize(size*2);
	}
	void set(int i, Node v, int x, int lx, int rx){
		if(rx-lx==1){
			arr[x] = v;
			return;
		}
		int m = (lx+rx)/2;
		if(i<m){
			set(i,v,2*x+1,lx,m);
		}
		else{
			set(i,v,2*x+2,m,rx);
		}
		arr[x] = merge(arr[2*x+1],arr[2*x+2]);
	}
	void set(int i, Node v){
		set(i,v,0,0,size);
	}
	Node query(int l,int r, int x, int lx, int rx){
		if(lx>=r||l>=rx)return Node();
		if(lx>=l&&rx<=r)return arr[x];
		int m = (lx+rx)/2;
		Node s1 = query(l,r,2*x+1,lx,m);
		Node s2 = query(l,r,2*x+2,m,rx);
		return merge(s1,s2);
	}
	Node query(int l, int r){
		return query(l,r,0,0,size);
	}
};

